package org.json;
import java.util.*;public class JSONObject {static Map<String,Map<String,Object>> saved=new HashMap<String,Map<String,Object>>();Map<String,Object> values=new HashMap<String,Object>();public JSONObject(){}public JSONObject(String s)throws JSONException {if(saved.containsKey(s))values.putAll(saved.get(s));else if(!s.equals("{}"))throw new JSONException("invalid");}public JSONObject put(String k,Object v)throws JSONException {values.put(k,v);return this;}public JSONArray optJSONArray(String k){return (JSONArray)values.get(k);}public String getString(String k)throws JSONException {return (String)values.get(k);}public boolean getBoolean(String k)throws JSONException {return (Boolean)values.get(k);}public String toString(){String k="fake-json-"+saved.size();saved.put(k,new HashMap<String,Object>(values));return k;}}
